{
  "story_id": "S05",
  "test_cases": [
    {
      "case_id": "TC01",
      "title": "Accept a claim submitted on the last permitted day",
      "covers": ["AC1", "AC3"],
      "preconditions": [
        "A claim has a treatment date of 10 March 2027."
      ],
      "steps": [
        "Set the claim submission date to 10 March 2028.",
        "Submit the claim for deadline assessment."
      ],
      "expected_result": "The claim is identified as submitted on time and is not routed to decline_recommended for late submission."
    },
    {
      "case_id": "TC02",
      "title": "Route a claim submitted one day after the deadline to decline recommendation",
      "covers": ["AC1", "AC3", "AC4"],
      "preconditions": [
        "A claim has a treatment date of 10 March 2027."
      ],
      "steps": [
        "Set the claim submission date to 11 March 2028.",
        "Submit the claim for deadline assessment."
      ],
      "expected_result": "The claim is identified as late and routed to decline_recommended with reason code LATE_SUBMISSION."
    },
    {
      "case_id": "TC03",
      "title": "Use 28 February as the deadline for treatment on 29 February",
      "covers": ["AC2", "AC3"],
      "preconditions": [
        "A claim has a treatment date of 29 February 2024."
      ],
      "steps": [
        "Set the claim submission date to 28 February 2025.",
        "Submit the claim for deadline assessment."
      ],
      "expected_result": "The claim is identified as submitted on time because 28 February 2025 is the last day to submit."
    },
    {
      "case_id": "TC04",
      "title": "Route a leap-day treatment claim submitted after 28 February to decline recommendation",
      "covers": ["AC2", "AC3", "AC4"],
      "preconditions": [
        "A claim has a treatment date of 29 February 2024."
      ],
      "steps": [
        "Set the claim submission date to 1 March 2025.",
        "Submit the claim for deadline assessment."
      ],
      "expected_result": "The claim is identified as late and routed to decline_recommended with reason code LATE_SUBMISSION."
    },
    {
      "case_id": "TC05",
      "title": "Assess timeliness using the claim submission date",
      "covers": ["AC1", "AC3"],
      "preconditions": [
        "A claim has a treatment date of 10 March 2027.",
        "The claim submission date is 10 March 2028."
      ],
      "steps": [
        "Set the assessment or processing date to 12 March 2028.",
        "Submit the claim for deadline assessment."
      ],
      "expected_result": "The claim is identified as submitted on time based on its submission date of 10 March 2028, regardless of the later assessment or processing date."
    }
  ]
}

