      "title": "Route a claim above 1,000 and within its category limit for manual review",
      "covers": ["AC1"],
      "preconditions": [
        "The claim's category limit is greater than 1,000.",
        "The claim is otherwise eligible for automatic approval."
      ],
      "steps": [
