        "Evaluate the claim's routing and recommendation."
      ],
      "expected_result": "The claim is routed to manual_review with reason code HIGH_VALUE and is not recommended for automatic approval."
    },
    {
      "case_id": "TC02",
      "title": "Do not classify a claim of exactly 1,000 as high value",
      "covers": ["AC2"],
      "preconditions": [
        "The claim's category limit is greater than 1,000."
      ],
      "steps": [
        "Submit a claim for exactly 1,000.",
        "Evaluate the claim's routing reason."
      ],
      "expected_result": "The claim is not classified or routed as HIGH_VALUE."
    },
    {
      "case_id": "TC03",
      "title": "Use OVER_LIMIT when a claim exceeds both its category limit and 1,000",
      "covers": ["AC1", "AC3"],
      "preconditions": [
        "The claim's category limit is 1,200."
      ],
      "steps": [
        "Submit a claim for 1,300.",
        "Evaluate the claim's routing and reason code."
      ],
      "expected_result": "The claim is routed with reason code OVER_LIMIT, not HIGH_VALUE, and is not recommended for automatic approval."
    }
  ]
}

{
  "story_id": "S10",
  "test_cases": [
    {
      "case_id": "TC01",
      "title": "Submit an appeal by replying to a declined-claim decision letter",
      "covers": ["AC1", "AC2"],
      "preconditions": [
        "The member has received a decision letter declining a claim."
      ],
      "steps": [
        "Reply to the decision letter to submit an appeal.",
        "State why the member believes the claim decision is wrong."
      ],
      "expected_result": "The appeal is received and recorded against the declined claim with the member's reason for disputing the decision."
    },
    {
      "case_id": "TC02",
      "title": "Submit an appeal through the member portal",
      "covers": ["AC1", "AC2"],
      "preconditions": [
        "The member can access the member portal.",
        "The member has a claim that was declined."
      ],
      "steps": [
        "Open the declined claim in the member portal.",
        "Choose the option to appeal the decision.",
        "Enter why the member believes the decision is wrong.",
        "Submit the appeal."
      ],
      "expected_result": "The portal accepts the appeal and records it against the declined claim, including the member's reason for disputing the decision."
    },
    {
      "case_id": "TC03",
      "title": "Include missing information with an appeal",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim and is submitting an appeal."
      ],
      "steps": [
        "Provide a reason why the decision is wrong.",
        "Include information missing from the original claim, such as a referral, pre-authorisation number, or provider description showing an injury was accidental.",
        "Submit the appeal."
      ],
      "expected_result": "The appeal records the member's reason and the additional information provided for review."
    },
    {
      "case_id": "TC04",
      "title": "Assign the appeal to a senior assessor not involved in the original decision",
      "covers": ["AC3"],
      "preconditions": [
        "A member has submitted an appeal against a declined claim.",
        "The original decision and the assessor who made it are recorded."
      ],
      "steps": [
        "Route the appeal for review.",
        "Check the role and prior involvement of the assigned reviewer."
      ],
      "expected_result": "The appeal is reviewed by a senior claims assessor who was not involved in the original decision."
    },
    {
      "case_id": "TC05",
      "title": "Do not assign an appeal to the original decision-maker",
      "covers": ["AC3"],
      "preconditions": [
        "A member has submitted an appeal against a declined claim.",
        "The original decision-maker is identifiable."
      ],
      "steps": [
        "Route the appeal for review when the original decision-maker is available."
      ],
      "expected_result": "The appeal is assigned to a senior claims assessor other than the original decision-maker."
    },
    {
      "case_id": "TC06",
      "title": "Route dissatisfaction with service as a complaint",
      "covers": ["AC4"],
      "preconditions": [
        "The member has expressed dissatisfaction with the service received but is not disputing the claim decision."
      ],
      "steps": [
        "Submit the member's concern through the appeal channel.",
        "Review how the concern is classified and routed."
      ],
      "expected_result": "The concern is handled as a complaint, not recorded or routed as an appeal."
    }
  ]
}
